package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.os.*;import android.text.*;import android.view.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={SpeechServiceTest.ManualTts.class,ReaderPlusTest.Microphone.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Bible513Test {
 WorkTestSupport w;@Before public void before()throws Exception{w=new WorkTestSupport();}@After public void close(){w.close();}
 String job(Uri uri,String name)throws Exception{return w.job("bible",new JSONObject().put("uri",uri.toString()).put("title","Bíblia de teste").put("name",name).put("mime",MediaFormats.mime(name,null)));}
 long verses(){try(PlusStore db=new PlusStore(w.app)){return DatabaseUtils.longForQuery(db.getReadableDatabase(),"SELECT COUNT(*) FROM bible_verses",null);}}
 File epub()throws Exception{File f=new File(w.app.getCacheDir(),"Bible.epub");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(f))){ChapterExportTest.entry(zip,"META-INF/container.xml","<container><rootfiles><rootfile full-path='book.opf'/></rootfiles></container>");ChapterExportTest.entry(zip,"book.opf","<package><metadata/><manifest><item id='one' href='one.xhtml' media-type='application/xhtml+xml'/><item id='two' href='two.xhtml' media-type='application/xhtml+xml'/></manifest><spine><itemref idref='one'/><itemref idref='two'/></spine></package>");ChapterExportTest.entry(zip,"one.xhtml","<html><body><h1>Isaías</h1><h2>Capítulo 5</h2><p>6 Texto exacto de Isaías cinco seis.</p><p>7 Outro versículo.</p></body></html>");ChapterExportTest.entry(zip,"two.xhtml","<html><body><h2>Capítulo 6</h2><p>1 Uma visão.</p><p>2 Serafins.</p></body></html>");}return f;}
 @Test public void structuredImportIsQueryableAndRepeatingACompletedCommitDoesNotDuplicateSources()throws Exception{Uri uri=w.source("bible","Bible.csv","livro,capitulo,versiculo,texto\nIsaías,5,6,Texto da passagem\nJoão,3,16,Outro texto\n");String id=job(uri,"Bible.csv");w.run(id);assertEquals(2,verses());w.run(id);try(PlusStore db=new PlusStore(w.app)){assertEquals(1,db.rows("bible_sources",null,null,null,10).size());assertEquals("Texto da passagem",db.rows("bible_verses","book=? AND chapter=5 AND verse=6",new String[]{"Isaías"},null,10).get(0).s("value"));}}
 @Test public void malformedImportNeverExposesAnEmptyOrPartiallyImportedTranslation()throws Exception{String id=job(w.source("bad","bad.csv","Isaías,5,6,Texto válido\nLinha ilegível sem referência\n"),"bad.csv");try{w.run(id);fail();}catch(IOException expected){}assertEquals(0,verses());try(PlusStore db=new PlusStore(w.app)){assertTrue(db.rows("bible_sources",null,null,null,10).isEmpty());}}
 @Test public void anEpubBibleInTheShelfCanBeIndexedWithBookChapterAndVerseHeadings()throws Exception{String id=job(w.source("epub","Bible.epub",epub()),"Bible.epub");w.run(id);assertEquals(4,verses());try(PlusStore db=new PlusStore(w.app)){assertEquals("Texto exacto de Isaías cinco seis.",db.rows("bible_verses","book=? AND chapter=5 AND verse=6",new String[]{"Isaías"},null,1).get(0).s("value"));}}
 @Test public void bookParserRetainsAnUnfinishedVerseAcrossPages()throws Exception{List<String> output=new ArrayList<>();BibleText.Sink sink=(b,c,v,t)->output.add(b+" "+c+":"+v+" "+t);BibleBookText first=new BibleBookText(sink,new JSONObject());first.feed("Isaías\nCapítulo 5\n6 Começo da passagem",()->false);BibleBookText resumed=new BibleBookText(sink,first.state());resumed.feed("Isaías\n24\ncontinua na página seguinte.\n7 Outro versículo.",()->false);resumed.flush();assertEquals(Arrays.asList("Isaías 5:6 Começo da passagem continua na página seguinte.","Isaías 5:7 Outro versículo."),output);}
 @Test public void chapterCheckpointWinsOverAnOlderTaskPayloadAfterAProcessStop()throws Exception{String id=job(w.source("epub","Bible.epub",epub()),"Bible.epub");File file=new File(SummaryWork.root(w.app,id),"bible.db");try(SQLiteDatabase stage=SQLiteDatabase.openOrCreateDatabase(file,null)){stage.execSQL("CREATE TABLE verses(book TEXT,chapter INTEGER,verse INTEGER,value TEXT,PRIMARY KEY(book,chapter,verse))");stage.execSQL("CREATE TABLE checkpoint(id INTEGER PRIMARY KEY,position INTEGER,value TEXT)");BibleBookText parser=new BibleBookText((b,c,v,t)->stage.insertOrThrow("verses",null,StudyStore.values("book",b,"chapter",c,"verse",v,"value",t)),new JSONObject());parser.feed("Isaías\nCapítulo 5\n6 Texto exacto de Isaías cinco seis.\n7 Outro versículo.",()->false);stage.execSQL("INSERT INTO checkpoint VALUES(1,1,?)",new Object[]{parser.state().toString()});}w.run(id);assertEquals(4,verses());}
 @Test public void separateVersesDoNotIncludeTheUnrequestedVerseBetweenThem(){java.util.List<int[]> selected=BibleReferences.intervals(BibleReferences.references("João 3:16,18; 4:2").get(0));assertEquals(3,selected.size());assertArrayEquals(new int[]{3,16,3,16},selected.get(0));assertArrayEquals(new int[]{3,18,3,18},selected.get(1));assertArrayEquals(new int[]{4,2,4,2},selected.get(2));java.util.List<int[]> range=BibleReferences.intervals(BibleReferences.references("João 3:16–4:2").get(0));assertEquals(1,range.size());assertArrayEquals(new int[]{3,16,4,2},range.get(0));}
 @Test public void nonBreakingHtmlSpacesBecomeClickableReferencesWithoutChangingTheDisplayedText(){String html="<p>Isaías&nbsp;5&#58;6</p>";String linked=BibleHtml.link(html);assertTrue(linked.contains("seekybible://passage"));assertTrue(linked.contains("Isaías\u00a05:6"));assertFalse(linked.contains("<a <a"));}
 @Test public void tappingTheActualReferenceOpensAPassageAboveTheSameReader()throws Exception{ReaderPlusTest fixture=new ReaderPlusTest();fixture.setup();ReaderActivity a=fixture.a;try{try(PlusStore db=new PlusStore(a)){long id=db.save("bible_sources",StudyStore.values("title","Consulta local","created",1));db.save("bible_verses",StudyStore.values("source",id,"book","Isaías","chapter",5,"verse",6,"value","A passagem abre sem abandonar a leitura."));}fixture.drain();a.bookText.measure(View.MeasureSpec.makeMeasureSpec(288,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));a.bookText.layout(0,0,288,a.bookText.getMeasuredHeight());int offset=a.bookText.getText().toString().indexOf("Isaías")+2;Layout layout=a.bookText.getLayout();float x=layout.getPrimaryHorizontal(offset)+a.bookText.getTotalPaddingLeft(),y=layout.getLineTop(layout.getLineForOffset(offset))+layout.getLineBottom(layout.getLineForOffset(offset));y=y/2+a.bookText.getTotalPaddingTop();a.bookText.dispatchTouchEvent(MotionEvent.obtain(100,100,MotionEvent.ACTION_DOWN,x,y,0));a.bookText.dispatchTouchEvent(MotionEvent.obtain(100,150,MotionEvent.ACTION_UP,x,y,0));for(int i=0;i<4;i++){PlusUi.WORK.submit(()->{}).get(15,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}assertTrue(BooksToolsTest.labels(ShadowDialog.getLatestDialog().getWindow().getDecorView()).contains("A passagem abre sem abandonar a leitura."));assertFalse(a.isFinishing());assertEquals(0,a.chrome.current());assertEquals("content://seeky.plus.reader/book",a.uri.toString());}finally{fixture.close();}}
}
